import picker from '@ohos.file.picker';
import photoAccessHelper from '@ohos.file.photoAccessHelper';
import web_webview  from '@ohos.web.webview';

import { getLogger } from "@coremail/mail_base"
import { getApp} from "../app/app"
import {  HostConfig } from '@coremail/mail_base'
import { AccountConfig } from "../app/data"
import { storage } from "../app/data"
import url from '@ohos.url';
import http from '@ohos.net.http';

const logger = getLogger('index-page')



@Component
struct ServerConfig {
  @Prop host: string;
  @Prop port: number;
  @Prop secure: boolean;

  build() {
    Column () {
      Text(this.host)
      Text(this.port.toString())
      Text(this.secure ? "SSL/TLS" : "")
    }
  }
}
@Entry(storage)
@Component
struct Index {
  @State message: string = '';
  @LocalStorageProp("accounts") accounts: string[] = []
  @LocalStorageProp("currentAccount") current: AccountConfig = {
    email: '',
    pass: '',
    smtp: { host: '', port: 0, secure: false },
    pop3: { host: '', port: 0, secure: false },
    imap: { host: '', port: 0, secure: false },
  }
  controller: web_webview.WebviewController = new web_webview.WebviewController()
  redirectUri: string = 'https://login.microsoftonline.com/common/oauth2/nativeclient'
  check?: (s: string) => boolean;

  @State buttons: [string, (event: ClickEvent) => Promise<void>][] = [
    ["获取文件夹列表", (event: ClickEvent) => getApp().testGetFolderList()],
    ["获取邮件基本信息", (event: ClickEvent) => getApp().testGetMail()],
    ["获取770邮件基本信息", (event: ClickEvent) => getApp().testGetMail2()],
    ["测试IMAP邮件头", (event: ClickEvent) => getApp().testGetImapMailHeader()],
    ["测试POP3邮件头", (event: ClickEvent) => getApp().testGetPop3MailHeader()],
    ["测试优先级", (event: ClickEvent) => getApp().testGetMailPriority()],
    ["发送邮件", (event: ClickEvent) => getApp().testSendMail()],
    ["base64", (event: ClickEvent) => getApp().testBase64()],
    ["oauth2", (event: ClickEvent) => getApp().testOAuth2((url: string, check: (s: string) => boolean) => {
      this.controller.loadUrl(url + '&username=qmoux%40outlook.com');
      this.check = check;
    })],
    ["搜索", (event: ClickEvent) => getApp().testSearch()],
    ["华为1", (event: ClickEvent) => getApp().testGetMailBasicAndGetMail()],
    ["华为2", (event: ClickEvent) => getApp().testDeleteMail()],
    ["测试复制多封邮件", (event: ClickEvent) => getApp().testCopyMails()],
    ["测试代发", (event: ClickEvent) => getApp().testDelegate()],
    ["测试序列化邮件", async (event: ClickEvent) => {
      /*
      let photoSelectOptions = new picker.PhotoSelectOptions();

      photoSelectOptions.MIMEType = picker.PhotoViewMIMETypes.IMAGE_TYPE;
      photoSelectOptions.maxSelectNumber = 1;
      let photoPicker = new photoAccessHelper.PhotoViewPicker();
      // let photoPicker = new picker.PhotoViewPicker();
      let photoSelectResult = await photoPicker.select(photoSelectOptions);
      if (photoSelectResult && photoSelectResult.photoUris && photoSelectResult.photoUris.length > 0) {
        logger.info('photo', photoSelectResult.photoUris);
      } else {
        // return [];
      }
      */
      const documentSelectOptions = new picker.DocumentSelectOptions();
      // documentSelectOptions.fileSuffixFilters = arr;
      // documentSelectOptions.maxSelectNumber = 10;
      let URI = "";
      const documentViewPicker = new picker.DocumentViewPicker();
      let result = await documentViewPicker.select(documentSelectOptions);
      logger.info('result', result);
      await getApp().testSerializeMail(result)
    }],
    ["测试队列", (event: ClickEvent) => getApp().testTaskQueue()],
    // ["测试viewmodel", (event: ClickEvent) => getApp().getViewModel()],
  ];

  build() {
    Row() {
      Column() {
        Select(this.accounts.map(value => ({ value } as SelectOption)))
          .value(this.current.email)
          .selected(this.accounts.indexOf(this.current.email))
          .onSelect((index: number, value: string) => {
            getApp().setAccount(value);
          })
        Button("测试连接")
          .onClick((event: ClickEvent) => {
            this.message = '';
            // getApp().testConnect().then(s => {
            //   this.message = s ? '连接成功' : '连接失败';
            // });
          })
        Text(this.message)

        Text(`SMTP: ${this.current.smtp.host}:${this.current.smtp.port} ${this.current.smtp.secure ? 'SSL/TLS' : ''}`)
        Text(`IMAP: ${this.current.imap.host}:${this.current.imap.port} ${this.current.imap.secure ? 'SSL/TLS' : ''}`)
        Text(`POP3: ${this.current.pop3.host}:${this.current.pop3.port} ${this.current.pop3.secure ? 'SSL/TLS' : ''}`)
      }
      .width(300)
      Column() {
        ForEach(this.buttons,
          (item: [string, (event: ClickEvent) => Promise<void>], index: number) => {
            Button(item[0])
              .onClick(item[1])
          })
      }
      .width(300)
      Column() {
        Web({ controller: this.controller, src: '' })
          .fileAccess(true)
          .javaScriptAccess(true)
          .layoutWeight(1)
          .onlineImageAccess(true)
          .domStorageAccess(true)
          .zoomAccess(true)
          .onLoadIntercept((event) => {
            logger.info('onLoadIntercept, ' + JSON.stringify(event));
            if (event.data) {
              const url = event.data.getRequestUrl();
              logger.info(url);
            }
            return false
          })
          .onPageVisible((event) => {
            logger.info('onPageVisible, ' + JSON.stringify(event));
            logger.info('onPageVisible, ', event.url);
            if (this.check && this.check(event.url)) {
              this.check = undefined;
            };
          })
      }
      .width(800)
    }
    .height('100%')
  }
}
